SCRIPT = r"""
(()=>{const root=document.documentElement;const initial=new URLSearchParams(location.search).get("theme");const saved=localStorage.getItem("novahost-theme");if(initial==="light"||initial==="dark")root.dataset.theme=initial;else if(saved)root.dataset.theme=saved;document.querySelectorAll("[data-theme-toggle]").forEach(b=>b.addEventListener("click",()=>{root.dataset.theme=root.dataset.theme==="light"?"dark":"light";localStorage.setItem("novahost-theme",root.dataset.theme)}));document.querySelectorAll("[data-copy]").forEach(b=>b.addEventListener("click",async()=>{const el=document.querySelector(b.dataset.copy);if(!el)return;try{await navigator.clipboard.writeText(el.innerText);b.textContent="Copied";setTimeout(()=>b.textContent="Copy",1200)}catch{b.textContent="Select and copy"}}));document.querySelectorAll("[data-filter]").forEach(input=>input.addEventListener("input",()=>{const selector=input.dataset.filter;document.querySelectorAll(selector).forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(input.value.toLowerCase()))}));document.querySelectorAll("[data-search-code]").forEach(input=>input.addEventListener("input",()=>{const query=input.value.toLowerCase();document.querySelectorAll(".code-line").forEach(line=>line.hidden=!!query&&!line.innerText.toLowerCase().includes(query))}));const img=document.querySelector("[data-image-viewer]");if(img){let scale=1,rotation=0,x=0,y=0;const update=()=>img.style.transform=`translate(${x}px,${y}px) scale(${scale}) rotate(${rotation}deg)`;document.querySelectorAll("[data-image-action]").forEach(b=>b.addEventListener("click",()=>{const action=b.dataset.imageAction;if(action==="in")scale=Math.min(8,scale*1.2);if(action==="out")scale=Math.max(.1,scale/1.2);if(action==="actual")scale=1;if(action==="fit"){scale=Math.min((innerWidth-70)/img.naturalWidth,(innerHeight-220)/img.naturalHeight,1)}if(action==="rotate")rotation+=90;if(action==="reset"){scale=1;rotation=0;x=0;y=0}update()}));img.addEventListener("load",()=>{const dims=document.querySelector("[data-image-dimensions]");if(dims)dims.textContent=`${img.naturalWidth} × ${img.naturalHeight}`});document.addEventListener("keydown",e=>{if(e.key==="+"||e.key==="=")scale=Math.min(8,scale*1.2);if(e.key==="-")scale=Math.max(.1,scale/1.2);if(e.key.toLowerCase()==="r")rotation+=90;if(e.key==="0"){scale=1;rotation=0;x=0;y=0}update()});let drag=null;img.addEventListener("pointerdown",e=>{drag={x:e.clientX-x,y:e.clientY-y};img.setPointerCapture(e.pointerId)});img.addEventListener("pointermove",e=>{if(drag){x=e.clientX-drag.x;y=e.clientY-drag.y;update()}});img.addEventListener("pointerup",()=>drag=null)}document.querySelectorAll("[data-media]").forEach(player=>{const media=player.querySelector("audio,video");const speed=player.querySelector("[data-speed]");const loop=player.querySelector("[data-loop]");if(speed)speed.addEventListener("change",()=>media.playbackRate=Number(speed.value));if(loop)loop.addEventListener("click",()=>{media.loop=!media.loop;loop.textContent=media.loop?"Loop on":"Loop off"});const theater=player.querySelector("[data-theater]");if(theater)theater.addEventListener("click",()=>player.querySelector(".media-stage").classList.toggle("is-theater"));const fs=player.querySelector("[data-fullscreen]");if(fs)fs.addEventListener("click",()=>{const el=player.querySelector(".media-stage");if(document.fullscreenElement)document.exitFullscreen();else el.requestFullscreen?.()});media.addEventListener("error",()=>{const n=player.querySelector("[data-media-error]");if(n)n.hidden=false})});document.querySelectorAll("[data-slideshow]").forEach(deck=>{const slides=[...deck.querySelectorAll("[data-slide]")];let index=0;const show=()=>{slides.forEach((s,i)=>s.hidden=i!==index);const counter=deck.querySelector("[data-slide-count]");if(counter)counter.textContent=`${index+1} / ${slides.length}`};deck.querySelector("[data-prev]")?.addEventListener("click",()=>{index=(index-1+slides.length)%slides.length;show()});deck.querySelector("[data-next]")?.addEventListener("click",()=>{index=(index+1)%slides.length;show()});document.addEventListener("keydown",e=>{if(e.key==="ArrowRight"){index=(index+1)%slides.length;show()}if(e.key==="ArrowLeft"){index=(index-1+slides.length)%slides.length;show()}});show()})})();
"""

ENHANCEMENTS = r"""
(()=>{document.querySelectorAll("[data-directory-sort]").forEach(select=>select.addEventListener("change",()=>{const list=document.querySelector(".directory-list");if(!list)return;const rows=[...list.querySelectorAll("[data-directory-row]")];const key=select.value;rows.sort((a,b)=>{if(key==="kind")return a.dataset.kind.localeCompare(b.dataset.kind)||a.dataset.name.localeCompare(b.dataset.name);if(key==="size")return Number(b.dataset.size)-Number(a.dataset.size)||a.dataset.name.localeCompare(b.dataset.name);if(key==="modified")return Number(b.dataset.modified)-Number(a.dataset.modified);if(key==="name-desc")return b.dataset.name.localeCompare(a.dataset.name);return Number(b.dataset.isDir)-Number(a.dataset.isDir)||a.dataset.name.localeCompare(b.dataset.name)});rows.forEach(row=>list.append(row))}));document.querySelectorAll("th[data-sort-column]").forEach((heading,index)=>heading.addEventListener("click",()=>{const body=heading.closest("table")?.tBodies[0];if(!body)return;const ascending=heading.dataset.direction!=="asc";heading.dataset.direction=ascending?"asc":"desc";const rows=[...body.rows];rows.sort((a,b)=>{const left=a.cells[index]?.innerText??"",right=b.cells[index]?.innerText??"";const ln=Number(left),rn=Number(right);const bothNumeric=left.trim()!==""&&right.trim()!==""&&Number.isFinite(ln)&&Number.isFinite(rn);return (bothNumeric?ln-rn:left.localeCompare(right,undefined,{numeric:true,sensitivity:"base"}))*(ascending?1:-1)});rows.forEach(row=>body.append(row))}));document.querySelectorAll("[data-media] video,[data-media] audio").forEach(media=>media.addEventListener("loadedmetadata",()=>{const target=media.closest("[data-media]")?.querySelector("[data-video-metadata]");if(target){const duration=Number.isFinite(media.duration)?`${Math.floor(media.duration/60)}:${String(Math.floor(media.duration%60)).padStart(2,"0")}`:"unknown duration";const dimensions=media.tagName==="VIDEO"?`${media.videoWidth} × ${media.videoHeight} · `:"";target.textContent=`${dimensions}${duration}`}}))})();
"""